'use strict';
const posterPath='share/poster-2026-v4.jpg';let posterFile=null,posterLoad=null;
function shareURL(root=false){const canonical=$('link[rel=canonical]')?.href||new URL('./',document.baseURI).href;const hash=location.hash.slice(1);return canonical+(!root&&/^(?:day-\d+|map(?:-\d+)?|itinerary|toolbox)$/.test(hash)?'#'+hash:'');}
function loadPosterFile(){if(!posterLoad)posterLoad=fetch(new URL(posterPath,document.baseURI)).then(r=>{if(!r.ok)throw Error('海报未加载');return r.blob();}).then(blob=>{posterFile=new File([blob],'Nordic-Journal-2026.jpg',{type:'image/jpeg'});return posterFile;}).catch(e=>{posterLoad=null;throw e;});return posterLoad;}
function shareJournal(){const wechat=/MicroMessenger/i.test(navigator.userAgent);openDrawer('分享这段旅程',`<img class="share-poster" src="${posterPath}" width="900" height="1350" alt="Nordic Journal 2026旅行海报，含可扫描打开正式网站的二维码"><p class="share-hint">${wechat?'微信内可长按上方图片保存，再发给好友或群聊；也可直接打开原图长按保存。':'保存海报后可发给朋友；二维码打开正式旅行路书。'}</p><div class="poster-actions"><a class="primary-link" href="${posterPath}" download="Nordic-Journal-2026.jpg">保存海报 ↓</a><a href="${posterPath}" target="_blank" rel="noopener">打开原图 ↗</a>${navigator.share&&navigator.canShare?'<button data-share-poster disabled>准备图片分享…</button>':''}</div><p id="posterStatus" class="share-hint" role="status"></p><div class="share-links">${navigator.share?'<button data-system-share>系统分享链接 ↗</button>':''}<button data-copy-link data-copy-root>复制旅行主页链接</button>${shareURL()!==shareURL(true)?'<button data-copy-link>复制当前日期链接</button>':''}</div><p class="share-hint">微信内可使用右上角菜单分享当前页面，也可保存海报发送给朋友。</p>`);if(navigator.share&&navigator.canShare)loadPosterFile().then(file=>{const button=$('[data-share-poster]');if(!button)return;if(navigator.canShare({files:[file]})){button.disabled=false;button.textContent='系统分享图片 ↗';}else button.hidden=true;}).catch(()=>{if($('#posterStatus'))$('#posterStatus').textContent='图片分享暂不可用，请打开原图或长按保存。';});}
async function sharePoster(){if(!posterFile||!navigator.canShare?.({files:[posterFile]})){toast('请长按海报或打开原图保存');return;}try{await navigator.share({files:[posterFile],title:'Nordic Journal 2026'});}catch(e){if(e.name!=='AbortError'&&$('#posterStatus'))$('#posterStatus').textContent='系统未完成图片分享，请长按保存后发送。';}}
async function systemShareLink(){try{await navigator.share({title:journalTitle,text:journalDescription,url:shareURL()});}catch(e){if(e.name!=='AbortError')await copyLink(shareURL());}}
